        "venue": "Главная Арена ГТО",
        "description": "🏆 Игры ГТО 2026 — Продвинутые команды — Часть А и Б (Синхронная)\n----------------------------------------------------------------------\n⏱ ЧАСТЬ А (0:00 - 11:00) — Синхронное ГТО (Time Cap: 11 минут)\n• Задача: Выполнить на время (For Time) 21-15-9 повторений:\n  - Синхронные трастеры (штанга 50 кг для мужчин / 35 кг для женщин)\n  - Выходы на перекладине (выполняются на двоих, распределение свободное)\n  - Синхронные взятия с виса + толчок (50/35 кг)\n  - Подъемы с переворотом (выполняются на двоих, распределение свободное)\n• Оценка: Время выполнения (макс. 100 баллов).\n\n🔔 ОТДЫХ 1 МИНУТА (11:00 - 12:00)\n\n⏱ ЧАСТЬ Б (12:00 - 20:00) — Синхронные берпи (AMRAP 8 минут)\n• Задача: За 8 минут набрать максимальное количество повторений:\n  - Синхронные берпи через штангу (фронтально)\n• Оценка: Количество выполненных берпи (макс. 100 баллов).",
