        "venue": "Арена ГТО, кампус ДВФУ",
        "description": "📍 Локация: Арена ГТО (4 соревновательные дорожки)\n\n🏁 ФИНАЛ — школьники. Три части.\n\nЧасть А — 12 минут. Каждый участник команды работает 2 минуты (отсечка каждые 2:00, затем в работу вступает следующий участник).\nЗа своё время — максимум циклов: лаз под ПВХ + прыжок через ПВХ (высота 50 см).\nРезультат части А: сумма выполненных циклов всех 6 участников.\n\nПереход — 1:00.\n\nЧасть Б — 12 минут. Команда делится на 3 пары М+Ж, каждая пара работает 4 минуты (отсечки 4:00 / 8:00 / 12:00).\nВ начале отрезка пара выполняет: 20/20 бросков мяча 6/3 кг через перекладину из положения седа; после бросков — максимум подъёмов по канату за оставшееся время.\nРезультат части Б: суммарное количество подъёмов по канату всех трёх пар.\n\nПереход — 1:00.\n\nЧасть В — 6 минут. Вся команда работает одновременно — максимум передач мяча 9 кг по цепочке (засчитываются только полностью выполненные передачи в установленном порядке).\nРезультат части В: количество передач мяча за 6 минут.\n\n📊 Результат каждой части — количество повторений.",
        "standards": "",
        "lanesCount": 4,
